// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Illusion".

Here, I'm going to use the film as an example. 
I play a bit on the motion illusion, obviously, but also on depth
and a bit on shape, by not drawing rectangles and circles as lines,
but creating them from a hatching.
*/

let theShader, dpr = window.devicePixelRatio, ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2596852/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
#define FC gl_FragCoord.xy
#define R resolution
#define T (25.+time)
#define S smoothstep
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define MN min(R.x,R.y)
// Function prototype.
float rnd(float a);
// Returns a value interpolated between two random values at a given point t with an exponent e
float curve(float t, float e) {
	t/=e;
	return mix(
		rnd(floor(t)),
		rnd(floor(t)-1.),
		pow(S(.0,1.,fract(t)),10.)
	);
}
// Returns a pseudo random number for a given number (white noise)
float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f);
	float
	a=rnd(i),
	b=rnd(i+vec2(1,0)),
	c=rnd(i+vec2(0,1)),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
	float t=.0, a=1., h=.0;
	for (float i=.0; i<5.; i++) {
		t+=a*noise(p);
		p*=2.;
		a*=.5;
		h+=a;
	}
	return t/h;
}
// Returns the hatched box and circle animation
// Based on this very cool demo by Kenji Saito:
// https://codepen.io/kenjiSpecial/full/ByWxGy
vec3 mov(vec2 p, float id, float t) {
	t+=id*.05;
  float
  na=rnd(FC),
  nb=rnd(vec2(FC.x,t)),
  nc=rnd(vec2(FC.y,t)),

  va=cos(t*2.)+2.,
  vb=sin(t*3.)+2.,
  vc=cos(t*2.)*1.5+2.,
  vd=cos(t*3.)+4.,
  ve=sin(t*2.)*3.+4.,

  t0=.1/abs(.5-length(p)*va)*nb*nc,
  t1=.1/abs(.5-max(abs(p.x+.1),abs(p.y-.2))*vb)*nb*nc,
  t2=.1/abs(.5-length(p+vec2(sin(T),cos(T)))*vd)*nb*nc,
  t3=.1/abs(.5-max(abs(p.x+.2),abs(p.y+.1))*ve)*nb*nc,
  t4=.1/abs(.5-length(p+vec2(-.1,.2))*vc)*nb*nc,

  tt=max(t4,max(t3,max(t2,max(t0,t1))));
  return vec3(tt*na*vc,tt*na*ve,tt*na*vd);
}
// Returns the distance to a box at the given point p with the given dimensions s
float box(vec2 p, vec2 s) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(p.x,p.y));
}
float background(vec2 p) {
	return fbm((2.-p)*4.+noise(p*.5));
}
// Returns the pattern of the film strip's perforations
float mask(vec2 p) {
	float id=floor(p.y*6.+.5);
	p.x=abs(p.x*4.)-1.5;
	p.y=fract(p.y*6.+.5)-.5;
	return SE(box(p*vec2(1,.6),vec2(.15,.1)),.05*(1.+.2*noise(floor(10.*fract(T))+id+p*4.+rnd(T+FC.x))));
}
// Returns the frames on the film strip
vec3 strip(vec2 p, float k) {
	float id=floor(p.y*2.+.5);
	p.y=fract(p.y*2.+.5)-.5;
	p.x*=3.;
	float d=SE(box(p,vec2(.9,.475)),.0);
	p.x/=3.;
	p.x*=2.;
	vec2 q=p;
	p*=5.;
	vec3 col=d*(.2+mov(p,id,floor(T)+.1*floor(10.*fract(T))));
	return mix(vec3(.5*k),col,k);
}
// Returns the mask combined with the perforations of the film strip
vec3 filmstrip(vec2 uv, float k) {
	vec2 p=uv;
	uv.y-=sin(T*62.8318)*.0075;
	uv.y+=.1*curve(T,.5)+T*S(.0,2.,sin(T));
	vec3 col=vec3(0);
	float d=SE(box((FC/R)*2.-1.,R.x>R.y?vec2(1,.9):vec2(.9,1)),.0);
	col+=mix(vec3(.5*k),max(strip(uv,k),mask(uv)*vec3(.6*k)),d);
	col=mix(vec3(0),col,S(-.1,.05,sin(2.*31.415*T)*.5+.5));
	return col;
}
// Returns the full-screen movie which is on the film strip
vec3 fullscene(vec2 uv) {
	vec3 col=vec3(0);
	col+=mov(uv*2.,.0,T);
	return col;
}
// The main entry of the shader
void main(void) {
	vec2 uv=(FC-.5*R)/MN;
	if (R.x>R.y) uv=vec2(uv.y,-uv.x);
	vec3 col=vec3(0);
	float k=background(uv);
	col=mix(filmstrip(uv,k),fullscene(uv),pow(S(.5,-.1,sin(T*(1.+curve(T*.2,5.)*.5))),16.));
	col=max(col,.08);
	O=vec4(col,1);
}

